 List<PadState> pads=[];string page="Inicio",deviceSignature="";readonly Dictionary<string,string> observedInstances=new();int player;int capture=-1;bool captureKey,armed;DateTime captureStart;PadState? lastPad;TextBlock? monitor;WrapPanel? signals;ComboBox? deviceBox;TextBlock? captureNote;Button? play;readonly List<Button> bindingButtons=[];readonly List<Button> keyButtons=[];bool changing,runningBefore,preparing;long ticks;
