 static Border Card(UIElement child)=>new(){Background=Brush("#14141A"),BorderBrush=Brush("#303039"),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(8),Padding=new Thickness(20),Margin=new Thickness(0,0,0,16),Child=child};
 public MainWindow(Store? customStore=null){store=customStore??new();InitializeComponent();game=new(store);Loaded+=(_,_)=>{Status.Text=store.Warning??(RomService.GameReady(store)?"Juego preparado. Elige Start.":"Selecciona tu ROM para comenzar.");Navigate("Inicio");play?.Focus();timer.Start();};timer.Tick+=Tick;Closing+=(_,_)=>{timer.Stop();store.Save();game.Close();inputs.Dispose();};PreviewKeyDown+=CaptureKey;
  foreach(string title in new[]{"General","Controles","Gráficos","Sonido"}){var b=Button(title,()=>Navigate(title));b.Style=(Style)FindResource("TabButton");Navigation.Children.Add(b);}
