 void Navigate(string target){CancelCapture();page=target;Page.Children.Clear();monitor=null;signals=null;deviceBox=null;bindingButtons.Clear();keyButtons.Clear();diagramButtons.Clear();PageScroll.ScrollToTop();
  OptionsOverlay.Visibility=target=="Inicio"?Visibility.Collapsed:Visibility.Visible;HomeSurface.Visibility=target=="Inicio"?Visibility.Visible:Visibility.Hidden;
  foreach(Button b in Navigation.Children){bool active=(string)b.Content==target;b.Foreground=Brush(active?"#F2C75C":"#B2B2BD");b.BorderBrush=Brush(active?"#F2C75C":"Transparent");}
  switch(target){case "Inicio":Home();break;case "General":GeneralPage();break;case "Controles":ControlsPage();break;case "Gráficos":GraphicsPage();break;case "Sonido":SoundPage();break;}
  if(target!="Inicio")Navigation.Children.OfType<Button>().First(b=>(string)b.Content==target).Focus();
 }
 void Home(){HomeMenu.Children.Clear();bool ready=RomService.Missing(store).Length==0;
  Button Menu(string label,Action action){var b=Button(label,action);b.Style=(Style)FindResource("MenuButton");b.HorizontalAlignment=HorizontalAlignment.Stretch;HomeMenu.Children.Add(b);return b;}
  play=Menu(game.Running?"Partida en curso":ready?"Start":"Seleccionar ROM",async()=>{if(ready)await Launch();else await Import();});play.IsEnabled=!game.Running&&!preparing;
  Menu("Controles",()=>Navigate("Controles"));Menu("Opciones",()=>Navigate("General"));if(game.Running)Menu("Cerrar partida",()=>game.Stop());Menu("Salir",Close);
 }
 async Task Import(){
  if(game.Running){Status.Text="Cierra la partida antes de cambiar la ROM.";return;}if(preparing)return;
  var dlg=new OpenFileDialog{Title="Seleccionar tu ROM de TECMO World Cup 98",Filter="ROM del juego (ZIP)|*.zip",CheckFileExists=true};if(dlg.ShowDialog(this)!=true)return;
  preparing=true;if(play!=null)play.IsEnabled=false;
  try{Status.Text="Verificando y preparando la ROM…";await Task.Run(()=>RomService.ImportNative(dlg.FileName,store));store.Value.RomSource=dlg.FileName;store.Save();Status.Text="ROM lista. Elige Start para jugar.";}
  catch(Exception ex){Status.Text=ex.Message;}finally{preparing=false;Navigate("Inicio");}
 }
 ComboBox Choice(string title,string[] choices,string selected,Action<string> changed,Panel parent){parent.Children.Add(Text(title,20));var c=new ComboBox{ItemsSource=choices,SelectedItem=choices.Contains(selected)?selected:choices[0],MaxWidth=480,HorizontalAlignment=HorizontalAlignment.Left,MinWidth=300};c.SelectionChanged+=(_,_)=>{if(c.SelectedItem is string s){changed(s);store.Save();}};parent.Children.Add(c);return c;}
 void Check(string title,bool value,Action<bool> changed,Panel panel){var c=new CheckBox{Content=title,IsChecked=value};c.Checked+=(_,_)=>{changed(true);store.Save();};c.Unchecked+=(_,_)=>{changed(false);store.Save();};panel.Children.Add(c);}
 void GeneralPage(){Page.Children.Add(Text("Preferencias",26));Check("Permitir mandos en segundo plano",store.Value.BackgroundInput,v=>store.Value.BackgroundInput=v,Page);Page.Children.Add(Text("Si lo desactivas, el juego solo recibe entradas cuando su ventana está activa.",16,"#AAAAB5"));Page.Children.Add(Text("Los ajustes se guardan automáticamente. Imagen y sonido se aplican a la siguiente partida.",16,"#AAAAB5"));}
 void InlineChoice(string title,string[] values,string selected,Action<string> change){Page.Children.Add(Text(title,22));var group=new WrapPanel{Margin=new Thickness(0,0,0,12)};string groupId=Guid.NewGuid().ToString();foreach(var value in values){var radio=new RadioButton{Content=value,GroupName=groupId,IsChecked=value==selected,Style=(Style)FindResource("InlineChoice")};radio.Checked+=(_,_)=>{change(value);store.Save();};group.Children.Add(radio);}Page.Children.Add(group);}
 void GraphicsPage(){InlineChoice("Modo de pantalla",["Ventana","Pantalla completa"],store.Value.Fullscreen?"Pantalla completa":"Ventana",v=>store.Value.Fullscreen=v=="Pantalla completa");InlineChoice("Tamaño de ventana",["960x720","1280x720","1280x960","1600x900","1920x1080","2560x1440","3840x2160"],store.Value.Resolution,v=>store.Value.Resolution=v);InlineChoice("Proporción",["Original","Estirar"],store.Value.Aspect,v=>store.Value.Aspect=v);InlineChoice("Tratamiento de imagen",["Nítido","Suave","Pixelart 2x"],store.Value.Filter,v=>store.Value.Filter=v);Page.Children.Add(Text("Nítido conserva los píxeles. Suave suaviza el escalado. Pixelart 2x suaviza bordes de píxeles antes de ampliar; puede cambiar detalles pequeños.",15,"#AAAAB5"));Page.Children.Add(Text("Original mantiene 4:3. Pantalla completa usa el tamaño del monitor. Se conserva la resolución interna y la velocidad del juego.",15,"#AAAAB5"));}
 void SoundPage(){Page.Children.Add(Text("Volumen general",26));var label=Text(AudioOptions.Level(store.Value)+" %",21,"#F2C75C");var slider=new Slider{Minimum=0,Maximum=100,Value=AudioOptions.Level(store.Value),TickFrequency=1,IsSnapToTickEnabled=true,SmallChange=1,LargeChange=10,Width=430,HorizontalAlignment=HorizontalAlignment.Left};System.Windows.Automation.AutomationProperties.SetName(slider,"Volumen general, de 0 a 100 por ciento");slider.ValueChanged+=(_,_)=>{store.Value.VolumePercent=(int)slider.Value;label.Text=store.Value.VolumePercent+" %";store.Save();};Page.Children.Add(label);Page.Children.Add(slider);Check("Silenciar (mute)",store.Value.Muted,v=>store.Value.Muted=v,Page);Page.Children.Add(Text("0 % es silencio. Mute conserva tu nivel para recuperarlo al desactivarlo. Se aplica en la siguiente partida.",16,"#AAAAB5"));Page.Children.Add(Text("Salida predeterminada de Windows. Este ajuste solo cambia el volumen del juego.",15,"#AAAAB5"));}
 PadState? SelectedPad()=>pads.FirstOrDefault(p=>p.Key==store.Value.Players[player].Device);
 PadProfile? Profile(){var p=SelectedPad();if(p==null)return null;if(!store.Value.Pads.TryGetValue(p.Key,out var c)){c=PadLogic.Default(p);store.Value.Pads[p.Key]=c;}return c;}
 public static string? KeyCode(Key k){if(k>=Key.A&&k<=Key.Z)return k.ToString().ToUpperInvariant();if(k>=Key.D0&&k<=Key.D9)return ((int)k-(int)Key.D0).ToString();if(k>=Key.NumPad0&&k<=Key.NumPad9)return ((int)k-(int)Key.NumPad0)+"PAD";return k switch{Key.Up=>"UP",Key.Down=>"DOWN",Key.Left=>"LEFT",Key.Right=>"RIGHT",Key.Space=>"SPACE",Key.LeftCtrl=>"LCONTROL",Key.RightCtrl=>"RCONTROL",Key.LeftAlt=>"LALT",Key.RightAlt=>"RALT",Key.LeftShift=>"LSHIFT",Key.RightShift=>"RSHIFT",Key.Enter=>"ENTER",Key.Tab=>"TAB",Key.Back=>"BACKSPACE",Key.Decimal=>"DELPAD",Key.Add=>"PLUSPAD",Key.Subtract=>"MINUSPAD",_=>null};}
 void Tick(object? sender,EventArgs e){try{ticks++;pads=inputs.Poll(store.Value.Backend);if(pads.Count>0&&store.Value.AutoAssignFirst&&store.Value.Players[0].Device==""&&!store.Value.Players.Any(x=>x.Device==pads[0].Key)){var first=pads[0];store.Value.Players[0].Device=first.Key;store.Value.Pads.TryAdd(first.Key,PadLogic.Default(first));store.Value.AutoAssignFirst=false;store.Save();Status.Text=first.Name+" asignado al jugador 1. Prueba sus entradas en Controles.";}DeviceSummary.Text=pads.Count==0?(inputs.Error!=null?"Error de lectura de mandos":"Sin mandos detectados"):$"{pads.Count} mando{(pads.Count>1?"s":"")} conectado{(pads.Count>1?"s":"")}";foreach(var p in pads){if(observedInstances.TryGetValue(p.Key,out var old)&&old!=p.SessionId&&observedInstances.Any(x=>x.Key!=p.Key&&x.Value==p.SessionId)){foreach(var pl in store.Value.Players.Where(x=>x.Device==p.Key))pl.Device="";Status.Text="Cambió el orden de dos mandos iguales. Vuelve a asignarlos a cada jugador.";}observedInstances[p.Key]=p.SessionId;}var signature=string.Join(';',pads.Select(p=>p.Key));if(signature!=deviceSignature){deviceSignature=signature;if(page=="Controles"){CancelCapture();Navigate("Controles");}}
  var masks=new int[4];var used=new HashSet<string>();for(int i=0;i<4;i++){var pad=pads.FirstOrDefault(p=>p.Key==store.Value.Players[i].Device);if(pad!=null&&used.Add(pad.Key)&&store.Value.Pads.TryGetValue(pad.Key,out var profile)){var v=PadLogic.Read(pad,profile);for(int a=0;a<10;a++)if(v[a]!=0)masks[i]|=1<<a;}}
  if(IsActive&&capture<0)NavigateWithPad();
  bool gameFocused=game.GameFocused;
  if(gameFocused)for(int i=0;i<4;i++)masks[i]|=KeyboardInput.Read(store.Value.Players[i]);
  bool blocked=(!store.Value.BackgroundInput&&!gameFocused)||capture>=0;if(blocked)Array.Clear(masks);if(game.Running){game.WriteState(masks);game.NoteInput(gameFocused,blocked,used.Count,inputs.Error);}
  if(game.Running!=runningBefore){runningBefore=game.Running;if(!runningBefore){game.FinishInputLog();Status.Text=game.ExitCode==0?"Partida cerrada. Lista para jugar otra vez.":"El juego terminó. Revisa el registro de la última sesión si hubo un problema.";}Home();}
  if(page=="Controles"&&IsActive){var pad=SelectedPad();var c=Profile();if(ticks%4==0)UpdateControlVisuals();if(monitor!=null&&ticks%4==0)monitor.Text=pad==null?(inputs.Error??"Sin señal. Conecta el mando o selecciona uno de la lista."):$"{pad.Driver} · {(pad.Standard?"normalizado":"asignación manual")}\nUSB {pad.Raw.VendorId}:{pad.Raw.ProductId} · {pad.Raw.ButtonCount} botones · {pad.Raw.Axes.Length} ejes · {pad.Hats.Length} HAT\nBotones: 0x{pad.Raw.Buttons:X}  HAT: {string.Join('/',pad.Hats)}\nEjes: {string.Join("  ",pad.Raw.Axes.Take(8).Select((v,i)=>$"{i+1}:{v:+0.00;-0.00;0.00}"))}";
   if(signals!=null&&ticks%5==0){signals.Children.Clear();if(pad!=null&&c!=null){var actions=PadLogic.Read(pad,c);for(int i=0;i<10;i++)if(actions[i]!=0)signals.Children.Add(new Border{Background=Brush("#F2C75C"),CornerRadius=new CornerRadius(4),Padding=new Thickness(8,4,8,4),Margin=new Thickness(0,0,8,0),Child=Text(Defaults.Actions[i],12,"#11271F")});}}
   if(capture>=0&&captureKey&&DateTime.UtcNow-captureStart>TimeSpan.FromSeconds(20)){CancelCapture();if(captureNote!=null)captureNote.Text="Se agotó la espera. Vuelve a elegir una acción.";}
   if(capture>=0&&!captureKey){if(DateTime.UtcNow-captureStart>TimeSpan.FromSeconds(20)){CancelCapture();captureNote!.Text="Se agotó la espera. Vuelve a elegir una acción.";}else if(pad==null){CancelCapture();captureNote!.Text="Mando desconectado. No se guardó la asignación.";}else{if(!armed){if(PadLogic.Neutral(pad)){armed=true;captureNote!.Text="Ahora pulsa el botón o dirección.";}}else if(lastPad!=null){var binding=PadLogic.Capture(lastPad,pad);if(binding!=null&&c!=null){int a=capture;if(c.Bindings.Where((_,i)=>i!=a).Any(b=>b==binding)){armed=false;captureNote!.Text="Esa entrada ya está asignada. Suelta el mando y elige otra.";}else{c.Bindings[a]=binding;store.Save();CancelCapture();RefreshBindingLabels();captureNote!.Text="Asignación guardada.";}}}lastPad=pad;}}
  }
 }catch(Exception ex){Status.Text="Entrada: "+ex.Message;}}

 async Task Launch(){if(preparing)return;try{var missing=RomService.Missing(store);if(missing.Length>0){Status.Text="No se puede iniciar: "+string.Join(", ",missing);return;}preparing=true;if(play!=null)play.IsEnabled=false;await Task.CompletedTask;game.Start();Status.Text="Partida abierta. Esc en el juego vuelve al menú.";Home();}catch(Exception ex){Status.Text=ex.Message;}finally{preparing=false;if(play!=null)play.IsEnabled=!game.Running;}}
 void BackClick(object sender,RoutedEventArgs e){Navigate("Inicio");play?.Focus();}
 void CaptureKey(object sender,KeyEventArgs e){
  if(e.Key==Key.Escape){if(capture>=0){CancelCapture();if(captureNote!=null)captureNote.Text="Asignación cancelada.";}else if(page!="Inicio"){Navigate("Inicio");play?.Focus();}e.Handled=true;return;}
  if(capture<0&&e.Key==Key.Enter&&Keyboard.FocusedElement is System.Windows.Controls.Primitives.ToggleButton toggle){toggle.IsChecked=toggle is RadioButton?true:toggle.IsChecked!=true;e.Handled=true;return;}
  if(capture<0||!captureKey)return;var key=e.Key==Key.System?e.SystemKey:e.Key;string? code=KeyCode(key);if(code==null){captureNote!.Text="Elige otra tecla.";e.Handled=true;return;}int a=capture;if(store.Value.Players[player].Keys.Where((_,i)=>i!=a).Contains(code)){captureNote!.Text="Esa tecla ya tiene una acción. Elige otra.";e.Handled=true;return;}store.Value.Players[player].Keys[a]=code;store.Save();if(keyButtons.Count>a)keyButtons[a].Content=code;CancelCapture();captureNote!.Text="Tecla guardada.";e.Handled=true;
 }
 void ExportDiagnostics(){var d=new SaveFileDialog{FileName="Tecmo98-controles.json",Filter="JSON|*.json"};if(d.ShowDialog(this)!=true)return;File.WriteAllText(d.FileName,System.Text.Json.JsonSerializer.Serialize(new{backend=store.Value.Backend,error=inputs.Error,devices=pads.Select(p=>new{p.Name,p.Driver,p.Family,p.Standard,p.Raw}),players=store.Value.Players.Select(p=>new{p.Number,p.Device})},new System.Text.Json.JsonSerializerOptions{WriteIndented=true}));Status.Text="Diagnóstico guardado en este equipo.";}
}
